class Solution:
    def maxStudents(self, seats):
        m, n = len(seats), len(seats[0])
        avail = []
        for i in range(m):
            v = 0
            for j in range(n):
                if seats[i][j] == '.':
                    v |= 1 << j
            avail.append(v)
        def gen(v):
            out = []
            for mk in range(1 << n):
                if mk & ~v == 0 and mk & (mk << 1) == 0:
                    out.append(mk)
            return out
        cand = [gen(v) for v in avail]
        prev = {0: 0}
        for i in range(m):
            cur = {}
            for mk in cand[i]:
                best = bin(mk).count('1')
                base = best
                for pm, pv in prev.items():
                    if mk & (pm << 1) == 0 and mk & (pm >> 1) == 0:
                        best = max(best, base + pv)
                cur[mk] = best
            prev = cur
        return max(prev.values())

