class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size(), n = seats[0].size();
        vector<int> avail(m, 0);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (seats[i][j] == '.') avail[i] |= 1 << j;
        vector<vector<int>> cand(m);
        for (int i = 0; i < m; i++)
            for (int mk = 0; mk < (1 << n); mk++)
                if ((mk & ~avail[i]) == 0 && (mk & (mk << 1)) == 0)
                    cand[i].push_back(mk);
        unordered_map<int,int> prev{{0,0}}, cur;
        for (int i = 0; i < m; i++) {
            cur.clear();
            for (int mk : cand[i]) {
                int pc = __builtin_popcount(mk), best = pc;
                for (auto& [pm, pv] : prev)
                    if (!(mk & (pm << 1)) && !(mk & (pm >> 1)))
                        best = max(best, pc + pv);
                cur[mk] = best;
            }
            prev = cur;
        }
        int ans = 0;
        for (auto& [k, v] : prev) ans = max(ans, v);
        return ans;
    }
};

