class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length, n = seats[0].length;
        int[] avail = new int[m];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (seats[i][j] == '.') avail[i] |= 1 << j;
        List<List<Integer>> cand = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            List<Integer> list = new ArrayList<>();
            for (int mk = 0; mk < (1 << n); mk++)
                if ((mk & ~avail[i]) == 0 && (mk & (mk << 1)) == 0)
                    list.add(mk);
            cand.add(list);
        }
        Map<Integer,Integer> prev = new HashMap<>(), cur = new HashMap<>();
        prev.put(0, 0);
        for (int i = 0; i < m; i++) {
            cur = new HashMap<>();
            for (int mk : cand.get(i)) {
                int pc = Integer.bitCount(mk), best = pc;
                for (Map.Entry<Integer,Integer> e : prev.entrySet()) {
                    int pm = e.getKey();
                    if ((mk & (pm << 1)) == 0 && (mk & (pm >> 1)) == 0)
                        best = Math.max(best, pc + e.getValue());
                }
                cur.put(mk, best);
            }
            prev = cur;
        }
        int ans = 0;
        for (int v : prev.values()) ans = Math.max(ans, v);
        return ans;
    }
}

