var maxStudents = function(seats) {
    const m = seats.length, n = seats[0].length;
    const avail = seats.map(row => {
        let v = 0;
        for (let j = 0; j < n; j++) if (row[j] === '.') v |= 1 << j;
        return v;
    });
    const cand = avail.map(v => {
        const list = [];
        for (let mk = 0; mk < (1 << n); mk++)
            if ((mk & ~v) === 0 && (mk & (mk << 1)) === 0) list.push(mk);
        return list;
    });
    let prev = new Map([[0, 0]]);
    for (let i = 0; i < m; i++) {
        const cur = new Map();
        for (const mk of cand[i]) {
            let best = [...Array(n)].reduce((c, _, b) => c + ((mk >> b) & 1), 0);
            const pc = best;
            for (const [pm, pv] of prev)
                if (!(mk & (pm << 1)) && !(mk & (pm >> 1)))
                    best = Math.max(best, pc + pv);
            cur.set(mk, best);
        }
        prev = cur;
    }
    return Math.max(...prev.values());
};

