class Solution:
    def maxStudents(self, seats):
        m, n = len(seats), len(seats[0])
        idx = [[-1] * n for _ in range(m)]
        cnt = 0
        for i in range(m):
            for j in range(n):
                if seats[i][j] == '.':
                    idx[i][j] = cnt
                    cnt += 1
        adj = [[] for _ in range(cnt)]
        for i in range(m):
            for j in range(n):
                if idx[i][j] < 0 or j % 2: continue
                for di, dj in ((0, 1), (1, -1), (1, 1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < m and 0 <= nj < n and idx[ni][nj] >= 0:
                        adj[idx[i][j]].append(idx[ni][nj])
        matchR = [-1] * cnt
        def aug(u, vis):
            for v in adj[u]:
                if vis[v]: continue
                vis[v] = True
                if matchR[v] == -1 or aug(matchR[v], vis):
                    matchR[v] = u
                    return True
            return False
        matching = 0
        for u in range(cnt):
            if aug(u, [False] * cnt):
                matching += 1
        return cnt - matching

