    vector<int> matchR;
    vector<bool> vis;
    bool aug(int u) {
        for (int v : adj[u]) {
            if (vis[v]) continue;
            vis[v] = true;
            if (matchR[v] == -1 || aug(matchR[v])) {
                matchR[v] = u;
                return true;
            }
        }
        return false;
    }
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size(), n = seats[0].size(), cnt = 0;
        vector<vector<int>> idx(m, vector<int>(n, -1));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (seats[i][j] == '.') idx[i][j] = cnt++;
        adj.assign(cnt, {});
        int dr[] = {0, 1, 1}, dc[] = {1, -1, 1};
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (idx[i][j] < 0 || j % 2) continue;
                for (int k = 0; k < 3; k++) {
                    int ni = i + dr[k], nj = j + dc[k];
                    if (ni >= 0 && ni < m && nj >= 0 && nj < n && idx[ni][nj] >= 0)
                        adj[idx[i][j]].push_back(idx[ni][nj]);
                }
            }
        matchR.assign(cnt, -1);
        int matching = 0;
        for (int u = 0; u < cnt; u++) {
            vis.assign(cnt, false);
            if (aug(u)) matching++;
        }
        return cnt - matching;
    }
};

