    const idx = Array.from({length: m}, () => Array(n).fill(-1));
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++)
            if (seats[i][j] === '.') idx[i][j] = cnt++;
    const adj = Array.from({length: cnt}, () => []);
    const dirs = [[0,1],[1,-1],[1,1]];
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++) {
            if (idx[i][j] < 0 || j % 2) continue;
            for (const [di, dj] of dirs) {
                const ni = i + di, nj = j + dj;
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && idx[ni][nj] >= 0)
                    adj[idx[i][j]].push(idx[ni][nj]);
            }
        }
    const matchR = Array(cnt).fill(-1);
    function aug(u, vis) {
        for (const v of adj[u]) {
            if (vis[v]) continue;
            vis[v] = true;
            if (matchR[v] === -1 || aug(matchR[v], vis)) {
                matchR[v] = u;
                return true;
            }
        }
        return false;
    }
    let matching = 0;
    for (let u = 0; u < cnt; u++)
        if (aug(u, Array(cnt).fill(false))) matching++;
